import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        V = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(V)]

    for u in range(V):
        line_parts = []
        try:
            while True:
                val = next(iterator)
                if val == '':
                    break
                line_parts.append(val)
        except StopIteration:
            pass

        for v_str in line_parts:
            v = int(v_str)
            adj[u].append(v)

    disc = [-1] * V
    low = [-1] * V
    parent = [-1] * V
    ap = set()
    timer = [0]

    def dfs(u):
        children = 0
        disc[u] = low[u] = timer[0]
        timer[0] += 1

        for v in adj[u]:
            if disc[v] == -1:
                children += 1
                parent[v] = u
                dfs(v)
                low[u] = min(low[u], low[v])

                if parent[u] == -1 and children > 1:
                    ap.add(u)
                if parent[u] != -1 and low[v] >= disc[u]:
                    ap.add(u)
            elif v != parent[u]:
                low[u] = min(low[u], disc[v])

    for i in range(V):
        if disc[i] == -1:
            dfs(i)

    if not ap:
        print("[-1]")
    else:
        result = sorted(list(ap))
        print(result)

if __name__ == "__main__":
    solve()
